window.AUTH=window.AUTH||{};window.AUTH["16-1140"]={"d":"16-1140","id":"2017/16-1140","n":"National Institute of Family and Life Advocates v. Becerra","briefs":[{"k":"petitioner","label":"Brief of petitioners NIFLA, et al.","date":"2018-01-08","url":"https://www.supremecourt.gov/DocketPDF/16/16-1140/26997/20180108123359506_2018.01.08%20NIFLAvB%20Brief%20of%20Petitioners%20FINAL.pdf","side":"pet","n":63},{"k":"united-states","label":"Brief amicus curiae of United States Supporting Neither Party","date":"2018-01-16","url":"https://www.supremecourt.gov/DocketPDF/16/16-1140/28033/20180116184704477_16-1140npacUnitedStates.pdf","side":"us","n":52},{"k":"respondent","label":"Brief of respondent Thomas E. Montgomery","date":"2018-02-20","url":"https://www.supremecourt.gov/DocketPDF/16/16-1140/35858/20180220120759477_16-1140%20Brief%20For%20Respondent.pdf","side":"res","n":33},{"k":"respondent","label":"Brief of respondents Becerra, Att'y Gen. of CA, et al.","date":"2018-02-20","url":"https://www.supremecourt.gov/DocketPDF/16/16-1140/35961/20180220155129758_2018.02.20.ussc.16-1140.jak.state_resp_merits_brief.pdf","side":"res","n":10},{"k":"reply","label":"Reply of petitioners NIFLA, et al.","date":"2018-03-13","url":"https://www.supremecourt.gov/DocketPDF/16/16-1140/38709/20180313112437769_2018.03.13%20NIFLAvB%20MERITS%20Reply%20Brief.pdf","side":"pet","n":25}],"opinion":null,"tr":true,"items":[{"t":"case","label":"44 Liquormart, Inc. v. Rhode Island","cite":"517 U.S. 484","y":1996,"id":"1995/94-1140","sc":1,"sum":"In a fractious opinion for a unanimous Court, Justice Stevens found Rhode Island's statutory ban on liquor price advertising to be an unconstitutional infringement of the liquor sellers' First Amendment right to freedom of speech.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Agency for International Development v. Alliance for Open Society International, Inc.","cite":"133 S. Ct. 2321","y":2013,"id":"2012/12-10","sc":1,"sum":"The Court held that it was a violation of the First Amendment to withhold funding from non-government organizations if they did not institute an anti-prostitution policy.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Ashcroft v. ACLU","cite":"542 U.S. 656","y":2004,"id":"2003/03-218","sc":1,"sum":"In an interesting 5-to-4 vote, with Justices Kennedy, Stevens, Souter, Thomas and Ginsburg on one side and Chief Justice Rehnquist and Justices Scalia, Breyer and O'Connor on the other, the Court found that Congress had not yet met its burden to show that the COPA requirements were more effective than other methods of preventing minors.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"Ashcroft v. Free Speech Coalition","cite":"535 U.S. 234","y":2002,"id":"2001/00-795","sc":1,"sum":"The Court held that the two prohibitions described above are overbroad and unconstitutional. The Court found the CPPA to be inconsistent with Miller insofar as the CPPA cannot be read to prohibit obscenity, because it lacks the required link between its prohibitions and the affront to community standards prohibited by the obscenity definition.","sumSrc":"Oyez","by":{"0":"24"}},{"t":"case","label":"Bigelow v. Virginia","cite":"421 U.S. 809","y":1975,"id":"1974/73-1309","sc":1,"sum":"The Court held that the Virginia law infringed upon Bigelow's First Amendment rights and violated the Constitution. Citing prior holdings such as New York Times v. Sullivan (1964), Justice Blackmun denied the Supreme Court of Virginia's ruling that commercial speech is not afforded First Amendment protection.","sumSrc":"Oyez","by":{"0":"49"}},{"t":"case","label":"Board of Trustees of State University of New York v. Fox","cite":"492 U.S. 469","y":1989,"id":"1988/87-2013","sc":1,"sum":"Resolution 66-156 of the State University of New York (SUNY) prohibits private commercial enterprises from operating in SUNY facilities. After the resolution was applied by campus police to bar American Future Systems, Inc. (AFS), from demonstrating and selling its housewares at a party hosted in a student dormitory, respondent Fox and other students sued for a declaratory judgment that such action violated the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20","1":"17, 18, 25, 27, 30"}},{"t":"case","label":"Brown v. Entertainment Merchants Association","cite":"564 U.S. 786","y":2011,"id":"2010/08-1448","sc":1,"sum":"The Court held that video games, including violent ones, are protected speech under the First Amendment.","sumSrc":"Oyez","by":{"0":"28, 49, 50, 51-52","1":"29","4":"19"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Central Hudson Gas and Electric Corporation v. Public Service Commission of New York","cite":"447 U.S. 557","y":1980,"id":"1979/79-565","sc":1,"sum":"The Court overruled the Court of Appeals of New York and held that the New York's ban violated the right to commercial speech. Writing for the majority, Justice Lewis F. Powell cited the protections for \"commercial speech from unwarranted governmental regulation\" set forth in Virginia Pharmacy Board v. Virginia Citizens Consumer Council .","sumSrc":"Oyez","by":{"0":"40, 60, 61","1":"12, 20"}},{"t":"case","label":"Church of the Lukumi Babalu Aye, Inc. v. City of Hialeah","cite":"508 U.S. 520","y":1993,"id":"1992/91-948","sc":1,"sum":"The Court found that an ordinance banning religious animal sacrifice was unconstitutional under the Free Exercise Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"34, 50"}},{"t":"case","label":"Citizens United v. Federal Election Commission","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Cohen v. California","cite":"403 U.S. 15","y":1971,"id":"1970/299","sc":1,"sum":"The Court ruled that a California statute prohibiting the display of offensive messages such as \"F--- the Draft\" violated freedom of expression as protected by the First Amendment.","sumSrc":"Oyez","by":{"0":"28"}},{"t":"case","label":"Edenfield v. Fane","cite":"507 U.S. 761","y":1993,"id":"1992/91-1594","sc":1,"sum":"As applied to CPA solicitation in the business context, Florida's prohibition is inconsistent with the free speech guarantees of the First and Fourteenth Amendments.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"40","1":"29"}},{"t":"case","label":"First National Bank of Boston v. Bellotti","cite":"435 U.S. 765","y":1978,"id":"1977/76-1172","sc":1,"sum":"The Court held that the right to attempt to influence the outcomes of elections is one of the primary rights the First Amendment was meant to protect. If this form of speech came from a person rather than a corporation, there would be no question about whether it was protected speech.","sumSrc":"Oyez","by":{"0":"35, 52","4":"2"}},{"t":"case","label":"Florida Bar v. Went For It, Inc.","cite":"515 U.S. 618","y":1995,"id":"1994/94-226","sc":1,"sum":"Lawyer advertising is commercial speech and as such, is accorded only a limited measure of First Amendment protection.","sumSrc":"Oyez","by":{"0":"22, 40"}},{"t":"case","label":"Gertz v. Robert Welch, Inc.","cite":"418 U.S. 323","y":1974,"id":"1973/72-617","sc":1,"sum":"Private individuals need only prove negligence to recover in defamation suits against news media","sumSrc":"Oyez","by":{"0":"25"}},{"t":"case","label":"Gonzales v. O Centro Espirita Beneficente Uniao do Vegetal","cite":"546 U.S. 418","y":2006,"id":"2005/04-1084","sc":1,"sum":"In a unanimous 8-0 decision (Justice Alito not participating), the Court held that the government had failed to prove a compelling interest in regulating the UDV's use of drugs for religious purposes. Writing for the Court, Chief Justice John Roberts rejected the government's argument that the Controlled Substances Act could accommodate no exceptions.","sumSrc":"Oyez","by":{"0":"50","4":"18"}},{"t":"case","label":"Hurley v. Irish–American Gay, Lesbian & Bisexual Group of Boston","cite":"515 U.S. 557","y":1995,"id":"1994/94-749","sc":1,"sum":"A unanimous court held that the State Court's ruling to require private citizens who organize a parade to include a group expressing a message that the organizers do not wish to convey violates the First Amendment by making private speech subordinate to the public accommodation requirement.","sumSrc":"Oyez","by":{"0":"23, 25","4":"6, 10, 11"}},{"t":"case","label":"King v. Governor of New Jersey","cite":"767 F.3d 216","y":2014,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/767/216/","by":{"0":"45","1":"17"}},{"t":"case","label":"Knox v. Service Employees International Union, Local 1000","cite":"132 S. Ct. 2277","y":2012,"id":"2011/10-1121","sc":1,"sum":"The Court found that, under the First Amendment, public-sector unions are not permitted to impose a special assessment fee without the consent of the member upon whom it is imposed.","sumSrc":"Oyez","by":{"0":"22, 39"}},{"t":"case","label":"Lamb’s Chapel v. Center Moriches Union Free School District","cite":"508 U.S. 384","y":1993,"id":"1992/91-2024","sc":1,"sum":"By a unaminous vote. The Supreme Court's holding consisted of two parts. First, the District violated freedom of speech by refusing the Chapel's request to show movies on school premises solely because such movies were religiously oriented.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Legal Services Corporation v. Velazquez","cite":"531 U.S. 533","y":2001,"id":"2000/99-603","sc":1,"sum":"The Court held that the funding provision that limited arguments legal services attorneys were allowed to make on behalf of indigent welfare claimants violated the First Amendment by regulating private speech and insulating federal law from legitimate judicial challenge.","sumSrc":"Oyez","by":{"0":"42, 59"}},{"t":"case","label":"Madsen v. Women’s Health Center, Inc.","cite":"512 U.S. 753","y":1994,"id":"1993/93-880","sc":1,"sum":"In a majority opinion authored by Chief Justice William H. Rehnquist, the Court found that the state of Florida could only restrict protesters to the extent necessary to allow the clinic to run and the staff to live in their homes without interference.","sumSrc":"Oyez","by":{"0":"60","1":"31"}},{"t":"case","label":"Matal v. Tam","cite":"137 S. Ct. 1744","y":2017,"id":"2016/15-1293","sc":1,"sum":"The Court determined that the Disparagement Clause prohibits trademarks that disparage the members of a racial or ethnic group and violates the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"31, 35, 42, 58, 59, 60"}},{"t":"case","label":"McCullen v. Coakley","cite":"134 S. Ct. 2518","y":2014,"id":"2013/12-1168","sc":1,"sum":"The Court ruled that the Massachusetts legislature violated the freedom of speech protections of the First Amendment when it created a 35-foot buffer around the entrances, exits and driveways of abortion clinics where political activity was prohibited.","sumSrc":"Oyez","by":{"0":"21, 28","4":"18, 20, 23"}},{"t":"case","label":"Members of City Council of Los Angeles v. Taxpayers for Vincent","cite":"466 U.S. 789","y":1984,"id":"1983/82-975","sc":1,"sum":"Section 28.04 of the Los Angeles Municipal Code prohibits the posting of signs on public property. Appellee Taxpayers for Vincent, a group of supporters of a candidate for election to the Los Angeles City Council, entered into a contract with appellee Candidates' Outdoor Graphics Service (COGS) to fabricate and post signs with the candidate's name on them. COGS produced cardboard signs and attached them to utility …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21","2":"25, 26"}},{"t":"case","label":"Miami Herald Publishing Company v. Tornillo","cite":"418 U.S. 241","y":1974,"id":"1973/73-797","sc":1,"ar":1,"sum":"The Court reversed the Supreme Court of Florida and held that Florida's \"right to reply\" statute violated the freedom of press found in the First Amendment. In an opinion written by Chief Justice Warren E. Burger, the Court recognized the risks posed to the \"true marketplace of ideas\" by media consolidation and barriers to entry in the newspaper industry.","sumSrc":"Oyez","by":{"0":"23, 38, 39","4":"6"}},{"t":"case","label":"Moore-King v. County of Chesterfield, Virginia","cite":"708 F.3d 560","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/708/560/","by":{"0":"45","1":"17"}},{"t":"case","label":"National Association for Advancement of Colored People v. Button","cite":"371 U.S. 415","y":1963,"id":"1962/5","sc":1,"sum":"Virginia's prosecution of the NAACP was constitutionally proscribed","sumSrc":"Oyez","by":{"0":"22, 41, 42, 44, 52-53, 57","1":"22","4":"14"}},{"t":"case","label":"National Institute of Family and Life Advocates v. Harris","cite":"2016 WL 3627327","y":2016,"court":"S.D. Cal. Feb. 9","by":{"0":"4"}},{"t":"case","label":"Pacific Gas and Electric Company v. Public Utilities Commission of California","cite":"475 U.S. 1","y":1986,"id":"1985/84-1044","sc":1,"sum":"The Commission's decision must be vacated. Remanded. JUSTICE POWELL, joined by THE CHIEF JUSTICE, JUSTICE BRENNAN, and JUSTICE O'CONNOR, concluded:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2, 23","4":"passim"}},{"t":"case","label":"Pickup v. Brown","cite":"740 F.3d 1208","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/740/1208/","by":{"0":"43","1":"17"}},{"t":"case","label":"Planned Parenthood Minnesota, North Dakota, South Dakota v. Rounds","cite":"530 F.3d 724","y":2008,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/530/724/","by":{"0":"48"}},{"t":"case","label":"Planned Parenthood of Southeastern Pennsylvania v. Casey","cite":"505 U.S. 833","y":1992,"id":"1991/91-744","sc":1,"sum":"A case in which the Court introduced a new standard of determining the validity of abortion laws by asking if the restrictions place any \"undue burden\" on the mother attempting to abort the fetus. If the restriction is found to do so, it is invalid.","sumSrc":"Oyez","by":{"0":"26, 46-47, 49","1":"10, 16, 18, 19, 20","3":"32","4":"15, 23"}},{"t":"case","label":"Posadas de Puerto Rico Associates v. Tourism Company of Puerto Rico","cite":"478 U.S. 328","y":1986,"id":"1985/84-1903","sc":1,"sum":"The Court held that the Act passed the constitutional test for restrictions on commercial speech.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"R.A.V. v. City of St. Paul","cite":"505 U.S. 377","y":1992,"id":"1991/90-7675","sc":1,"sum":"The Court found a Minnesota ordinance violated the First Amendment because the ordinance was overly broad in the content-based speech it prohibited.","sumSrc":"Oyez","by":{"0":"28, 29, 41, 42, 53"}},{"t":"case","label":"Reed v. Town of Gilbert","cite":"135 S. Ct. 2218","y":2015,"id":"2014/13-502","sc":1,"sum":"The Court decided that extra restrictions placed on signs describing the location of nonprofit events do not survive strict scrutiny and are therefore unconstitutional.","sumSrc":"Oyez","by":{"0":"15, 28, 31, 51","1":"19, 20","4":"2, 3, 19"}},{"t":"case","label":"Riley v. National Federation of the Blind of North Carolina, Inc.","cite":"487 U.S. 781","y":1988,"id":"1987/87-328","sc":1,"sum":"The North Carolina Charitable Solicitations Act defines the prima facie \"reasonable fee\" that a professional fundraiser may charge according to a three-tiered schedule. A fee up to 20% of receipts collected is deemed reasonable. A fee between 20% and 35% is deemed unreasonable upon a showing that the solicitation at issue did not involve the \"dissemination of information, discussion, or advocacy relating to public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"passim","1":"12, 23, 25, 28, 35","4":"passim"}},{"t":"case","label":"Rosenberger v. Rector and Visitors of University of Virginia","cite":"515 U.S. 819","y":1995,"id":"1994/94-329","sc":1,"sum":"The Court, in a 5-to-4 opinion, held that the University's denial of funding to Rosenberger, due to the content of his message, imposed a financial burden on his speech and amounted to viewpoint discrimination. The Court noted that no matter how scarce University publication funding may be, if it chooses to promote speech at all, it must promote all forms of it equally.","sumSrc":"Oyez","by":{"0":"31, 35, 39, 50, 58"}},{"t":"case","label":"Roth v. United States","cite":"354 U.S. 476","y":1957,"id":"1956/582","sc":1,"sum":"The Court found that obscene materials are not within the protective scope of the First Amendment.","sumSrc":"Oyez","by":{"0":"40"}},{"t":"case","label":"Rust v. Sullivan","cite":"500 U.S. 173","y":1991,"id":"1990/89-1391","sc":1,"sum":"The Court held that the \"regulations promulgated by the Secretary [of HHS] do not raise the sort of 'grave and doubtful constitutional questions' that would lead us to assume Congress did not intend to authorize their issuance.\" Should government subsidize one protected right (family planning), as it does in this case, it does not follow that government must subsidize analogous counterpart rights (abortion services).","sumSrc":"Oyez","by":{"0":"21, 56"}},{"t":"case","label":"Schneider v. New Jersey","cite":"308 U.S. 147","y":1939,"id":"1900-1940/308us147","sc":1,"sum":"The Court held that the municipal bans on hand-to-hand distribution of pamphlets violated the First Amendment.","sumSrc":"Oyez","by":{"0":"54, 56"}},{"t":"case","label":"Schneiderman v. United States","cite":"320 U.S. 118","y":1943,"id":"scdb/1942-045","sc":1,"sum":"(1) That the evidence, which is reviewed in the opinion, fails to show with the requisite degree of certainty that during the period in question the defendant was not attached to the principles of the Constitution. P. 135. (2) Attachment to the principles of the Constitution is not necessarily incompatible with a desire to have it amended. P. 137. (3) Utterances of certain leaders of the party organizations in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"24"}},{"t":"case","label":"Secretary of State of Maryland v. Joseph H. Munson Company","cite":"467 U.S. 947","y":1984,"id":"1983/82-766","sc":1,"sum":"A Maryland statute prohibits a charitable organization, in connection with any fundraising activity, from paying expenses of more than 25% of the amount raised, but authorizes a waiver of this limitation where it would effectively prevent the organization from raising contributions. Respondent is a professional fundraiser whose Maryland customers include various chapters of the Fraternal Order of Police, at least …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 53, 54"}},{"t":"case","label":"Snyder v. Phelps","cite":"562 U.S. 443","y":2011,"id":"2010/09-751","sc":1,"sum":"The Court held that the Westboro Baptist Church was protected under the First Amendment while picketing a military funeral.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Sorrell v. IMS Health, Inc.","cite":"564 U.S. 552","y":2011,"id":"2010/10-779","sc":1,"ar":1,"sum":"The Court held that a Vermont statute banning the sale, transmission or use of prescription drug user data violated protected speech of the pharmaceutical research companies, manufacturers and others who use that data.","sumSrc":"Oyez","by":{"0":"passim","1":"31","4":"4, 5, 7, 17, 19"}},{"t":"case","label":"Stenberg v. Carhart","cite":"530 U.S. 914","y":2000,"id":"1999/99-830","sc":1,"sum":"In a complicated 5-4 decision delivered by Justice Stephen G. Breyer, the Court held that \"Nebraska's statute criminalizing the performance of \"partial birth abortion[s]\" violates the U.S. Constitution, as interpreted in Casey and Roe.\" The sharply divided Court struck down the statute because it placed an undue burden on a woman's right to have an abortion and did not allow for exception in cases of threatened health. \"All those who perform abortion procedures using that method must fear prosecution, conviction, and imprisonment,\" that results in \"an undue burden upon a woman's right to make an abortion decision,\" wrote Justice Breyer for the Court.","sumSrc":"Oyez","by":{"0":"26","1":"24"}},{"t":"case","label":"Stuart v. Camnitz","cite":"774 F.3d 238","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/774/238/","by":{"0":"48","1":"19"}},{"t":"case","label":"Texas Medical Providers Performing Abortion Services v. Lakey","cite":"667 F.3d 570","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/667/570/","by":{"0":"48"}},{"t":"case","label":"Thomas v. Collins","cite":"323 U.S. 516","y":1945,"id":"1940-1955/323us516","sc":1,"sum":"The law was unconstitutional. It interfered with freedom of speech and freedom of assembly which possesses \"a sanctity and a sanction not permitting dubious intrusions.\".","sumSrc":"Oyez","by":{"0":"47"}},{"t":"case","label":"Turner Broadcasting System, Inc. v. F.C.C.","cite":"512 U.S. 622","y":1994,"id":"1993/93-44","sc":1,"sum":"The Court held that the must-carry provisions were content neutral, thus not a violation of the First Amendment. The rules were not determined by the programming content, but by broadcast method. The rules promote fair competition in television programming.","sumSrc":"Oyez","by":{"0":"22, 34, 54","1":"12, 27, 28","4":"3, 4, 25"}},{"t":"case","label":"United States v. Alvarez","cite":"567 U.S. 709","y":2012,"id":"2011/11-210","sc":1,"sum":"The Court found that the Stolen Valor Act violated the First Amendment.","sumSrc":"Oyez","by":{"0":"29, 30"}},{"t":"case","label":"United States v. Playboy Entertainment Group","cite":"529 U.S. 803","y":2000,"id":"1999/98-1682","sc":1,"sum":"The Court held that because the Federal Government failed to show that section 505 was the least restrictive means to further its interests, requiring cable television operators to fully scramble or limit time when sexually-oriented programming was transmitted violated the First Amendment's free speech guarantee.","sumSrc":"Oyez","by":{"0":"49-50, 54","4":"18, 20"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"0":"30"}},{"t":"case","label":"United States v. Swisher","cite":"811 F.3d 299","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/811/299/","by":{"0":"29"}},{"t":"case","label":"Village of Schaumburg v. Citizens for a Better Environment","cite":"444 U.S. 620","y":1980,"id":"1979/78-1335","sc":1,"sum":"The Court held that charitable solicitation is not purely commercial speech and is closely related to forms of protected speech such as advocacy. Justice Byron R. White, who authored the majority opinion, argued that \"it is clear\" that charitable solicitations are protected.","sumSrc":"Oyez","by":{"0":"24, 54, 57, 61"}},{"t":"case","label":"Virginia State Board of Pharmacy v. Virginia Citizens Consumer Council, Inc.","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"sum":"In a 7-to-1 opinion, the Court held that the First Amendment protects willing speakers and willing listeners equally. The Court noted that in cases of commercial speech, such as price advertising, freedom of speech protections apply just as they would to noncommercial speech. Even speech that is sold for profit, or involves financial solicitations, is protected.","sumSrc":"Oyez","by":{"0":"21","1":"21"}},{"t":"case","label":"Watchtower Bible and Tract Society of New York, Inc. v. Village of Stratton","cite":"536 U.S. 150","y":2002,"id":"2001/00-1737","sc":1,"sum":"The Court held that the ordinance's provisions making it a misdemeanor to engage in door-to-door advocacy without first registering with the mayor and receiving a permit violate the First Amendment as it applies to religious proselytizing, anonymous political speech, and the distribution of handbills.","sumSrc":"Oyez","by":{"0":"41, 53, 54"}},{"t":"case","label":"West Virginia State Board of Education v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"sum":"The Court found that a West Virginia statute requiring students and teachers say the Pledge of Allegiance, under threat of expulsion and delinquency charges, was unconstitutional.","sumSrc":"Oyez","by":{"0":"23, 24, 58","1":"12","4":"3"}},{"t":"case","label":"Wollschlaeger v. Governor, Florida","cite":"848 F.3d 1293","y":2017,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/848/1293/","by":{"0":"43, 44"}},{"t":"case","label":"Wooley v. Maynard","cite":"430 U.S. 705","y":1977,"id":"1976/75-1453","sc":1,"sum":"In a 6-to-3 decision, the Court held that New Hampshire could not constitutionally require citizens to display the state motto upon their vehicle license plates.","sumSrc":"Oyez","by":{"0":"1, 23, 24, 25","1":"11, 12, 28","4":"6, 9"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"stext":{"head":"§1254. Courts of appeals; certiorari; certified questions","paras":[[0,"Cases in the courts of appeals may be reviewed by the Supreme Court by the following methods:"],[1,"(1) By writ of certiorari granted upon the petition of any party to any civil or criminal case, before or after rendition of judgment or decree;"],[1,"(2) By certification at any time by a court of appeals of any question of law in any civil or criminal case as to which instructions are desired, and upon such certification the Supreme Court may give binding instructions or require the entire record to be sent up for decision of the entire matter in controversy."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1254?type=usc&year=mostrecent&link-type=html"},"head":"§1254. Courts of appeals; certiorari; certified questions","tname":"Judiciary and Judicial Procedure","by":{"0":"4","2":"2"}},{"t":"usc","label":"42 U.S.C. § 238n","url":"https://www.law.cornell.edu/uscode/text/42/238n","stext":{"head":"§238n. Abortion-related discrimination in governmental activities regarding training and licensing of physicians","paras":[[0,"(a) In general"],[0,"The Federal Government, and any State or local government that receives Federal financial assistance, may not subject any health care entity to discrimination on the basis that—"],[1,"(1) the entity refuses to undergo training in the performance of induced abortions, to require or provide such training, to perform such abortions, or to provide referrals for such training or such abortions;"],[1,"(2) the entity refuses to make arrangements for any of the activities specified in paragraph (1); or"],[1,"(3) the entity attends (or attended) a post-graduate physician training program, or any other program of training in the health professions, that does not (or did not) perform induced abortions or require, provide or refer for training in the performance of induced abortions, or make arrangements for the provision of such training."],[0,"(b) Accreditation of postgraduate physician training programs"],[0,"(1) In general"],[1,"In determining whether to grant a legal status to a health care entity (including a license or certificate), or to provide such entity with financial assistance, services or other benefits, the Federal Government, or any State or local government that receives Federal financial assistance, shall deem accredited any postgraduate physician training program that would be accredited but for the accrediting agency's reliance upon an accreditation standards 1 that requires an entity to perform an induced abortion or require, provide, or refer for training in the performance of induced abortions, or make arrangements for such training, regardless of whether such standard provides exceptions or exemptions. The government involved shall formulate such regulations or other mechanisms, or enter into such agreements with accrediting agencies, as are necessary to comply with this subsection."],[0,"(2) Rules of construction"],[0,"(A) In general"],[2,"With respect to subclauses (I) and (II) of section 292d(a)(2)(B)(i) of this title (relating to a program of insured loans for training in the health professions), the requirements in such subclauses regarding accredited internship or residency programs are subject to paragraph (1) of this subsection."],[0,"(B) Exceptions"],[2,"This section shall not—"],[3,"(i) prevent any health care entity from voluntarily electing to be trained, to train, or to arrange for training in the performance of, to perform, or to make referrals for induced abortions; or"],[3,"(ii) prevent an accrediting agency or a Federal, State or local government from establishing standards of medical competency applicable only to those individuals who have voluntarily elected to perform abortions."],[0,"(c) Definitions"],[0,"For purposes of this section:"],[1,"(1) The term \"financial assistance\", with respect to a government program, includes governmental payments provided as reimbursement for carrying out health-related activities."],[1,"(2) The term \"health care entity\" includes an individual physician, a postgraduate physician training program, and a participant in a program of training in the health professions."],[1,"(3) The term \"postgraduate physician training program\" includes a residency training program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/238n?type=usc&year=mostrecent&link-type=html"},"head":"§238n. Abortion-related discrimination in governmental activities regarding training and licensing of physicians","tname":"The Public Health and Welfare","by":{"0":"14","1":"7, 32"}},{"t":"case","label":"American Meat Inst. v. United States Dep’t of Agric.","cite":"760 F.3d 18","y":2014,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/760/18/","by":{"1":"15"}},{"t":"case","label":"Barker v. Capotosto","cite":"875 N.W.2d 157","y":2016,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/875/157/","by":{"1":"21"}},{"t":"case","label":"Barsky v. Board of Regents","cite":"347 U.S. 442","y":1954,"id":"scdb/1953-067","sc":1,"sum":"The New York law, on its face or as so construed and applied, does not violate the Due Process Clause of the Fourteenth Amendment. Pp. 443-456. _ (a) The decision of the highest state court that a violation of 2 U. S. C. § 192, though not a crime under New York law, was a \"crime\" within the meaning of § 6514-2 (b) of the State Education Law, is conclusive here.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"(III) Cases—Continued: Bolger v. Youngs Drug Prods. Corp.","cite":"463 U.S. 60","y":1983,"id":"1982/81-1590","sc":1,"sum":"As applied to appellee's proposed mailings, § 3001(e)(2) is unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21, 22","4":"11"}},{"t":"case","label":"CTIA-The Wireless Ass’n v. City of Berkeley","cite":"854 F.3d 1105","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/854/1105/","by":{"1":"15"}},{"t":"case","label":"Centro Tepeyac v. Montgomery County","cite":"722 F.3d 184","y":2013,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/722/184/","by":{"1":"26, 34"}},{"t":"case","label":"Christian Legal Soc’y Chapter of the Univ. of Cal. v. Martinez","cite":"561 U.S. 661","y":2010,"id":"2009/08-1371","sc":1,"sum":"The Court held that a college's mandate requiring all officially-recognized student organizations be inclusive and welcoming to all students did not violate a group of Christian students' First Amendment rights when the college refused to recognize a student group that required all members to sign a statement of Christian beliefs for membership.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"City of Cincinnati v. Discovery Network, Inc.","cite":"507 U.S. 410","y":1993,"id":"1992/91-1200","sc":1,"sum":"The city's selective and categorical ban on the distribution, via newsrack, of \"commercial handbills\" is not consistent with the dictates of the First Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"18, 30"}},{"t":"case","label":"Dent v. West Va.","cite":"129 U.S. 114","y":1889,"id":"scdb/1888-092","sc":1,"sum":"The statute of West Virginia (§§ 9 and 15, chapter 93, 1882) which requires every practitioner ofmedicine in the State to. obtain a certificate from the State Board of Health that he is a graduate of a reputable medi-._ cal college in the school of medicine to which hebelongs; or that he has. practised medicine in the State continuously for ten years prior to March 8, 1881; of that he has been found upon examination …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Evergreen Ass’n, Inc. v. City of N.Y.","cite":"740 F.3d 233","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/740/233/","by":{"1":"28, 34"}},{"t":"case","label":"Expressions Hair Design v. Schneiderman","cite":"137 S. Ct. 1144","y":2017,"id":"2016/15-1391","sc":1,"sum":"The Court decided that the New York General Business Law’s was not unconstitutionally vague under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"1":"20, 36"}},{"t":"case","label":"Goldfarb v. Virginia State Bar","cite":"421 U.S. 773","y":1975,"id":"1974/74-70","sc":1,"sum":"The minimumfee schedule, as published by the County Bar Association and enforced by the State Bar, violates § 1 of the Sherman Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"15"}},{"t":"case","label":"Greater Balt. Ctr. for Pregnancy Concerns, Inc. v. Mayor & City Council of Baltimore","cite":"2018 WL 298142","y":2018,"court":"4th Cir. Jan. 5","by":{"1":"32"}},{"t":"case","label":"Ibanez v. Florida Dep’t of Bus. & Prof ’l Regulation","cite":"512 U.S. 136","y":1994,"id":"1993/93-639","sc":1,"ar":1,"sum":"The Court held that Ibanez's use of her CPA and CFP designations constituted commercial speech, which can only be restricted if it can be proven to be false or misleading and the state has a substantial interest in restricting it. Because Ibanez is fully licensed, her use of the designations was neither false nor misleading.","sumSrc":"Oyez","by":{"1":"15, 35","4":"8"}},{"t":"case","label":"Lowe v. SEC","cite":"472 U.S. 181","y":1985,"id":"1984/83-1911","sc":1,"sum":"Petitioners' publications fall within the statutory exclusion for bona fide publications, none of the petitioners is an \"investment adviser\" as defined in the Act, and therefore neither petitioners' unregistered status nor the SEC order against Lowe provides a justification for restraining the future publication of their newsletters.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16","4":"14"}},{"t":"case","label":"Milavetz, Gallop & Milavetz P. A. v. United States","cite":"559 U.S. 229","y":2010,"id":"2009/08-1119","sc":1,"sum":"The Court held that attorneys who provide bankruptcy assistance are debt relief agencies under the Bankruptcy Abuse Prevention and Consumer Protection Act.","sumSrc":"Oyez","by":{"1":"14, 15, 20","4":"11"}},{"t":"case","label":"New York State Rest. Ass’n v. New York City Bd. of Health","cite":"556 F.3d 114","y":2009,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/556/114/","by":{"1":"15"}},{"t":"case","label":"Ohralik v. Ohio State Bar Ass’n","cite":"436 U.S. 447","y":1978,"id":"1977/76-1650","sc":1,"ar":1,"sum":"The Court held that a state may constitutionally discipline a lawyer for soliciting clients in person and for financial gain under circumstances likely to pose dangers that the state has a right to prevent.","sumSrc":"Oyez","by":{"1":"10, 13, 16, 17, 18"}},{"t":"case","label":"Polk County v. Dodson","cite":"454 U.S. 312","y":1981,"id":"1981/80-824","sc":1,"sum":"Respondent brought suit in Federal District Court under 42 U. S. C. § 1983 against petitioners Polk County, its Offender Advocate, its Board of Supervisors, and Martha Shepard, an attorney in the Offender Advocate's Office. As the factual basis for his lawsuit, respondent alleged that Shepard, who had been assigned to represent him in an appeal of a criminal conviction to the Iowa Supreme Court, failed to represent …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"R.J. Reynolds Tobacco Co. v. FDA","cite":"696 F.3d 1205","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/696/1205/","by":{"1":"15"}},{"t":"case","label":"Rubin v. Coors Brewing Co.","cite":"514 U.S. 476","y":1995,"id":"1994/93-1631","sc":1,"sum":"a case in which the Court held that for the government to regulate commercial speech, the government must have a substantial interest that the regulation directly affects.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Shapero v. Kentucky Bar Ass’n","cite":"486 U.S. 466","y":1988,"id":"1987/87-16","sc":1,"sum":"Justice William J. Brennan wrote the majority opinion, holding the Kentucky Supreme Court rule unconstitutional. The Supreme Court did not decide whether Shapero’s letter required First Amendment protections. The Court remanded the case for further consideration of that issue.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Thompson v. Western States Med. Ctr.","cite":"535 U.S. 357","y":2002,"id":"2001/01-344","sc":1,"sum":"The Court held that the FDAMA's provisions amounted to unconstitutional restrictions on commercial speech.","sumSrc":"Oyez","by":{"1":"28","4":"21"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"sum":"Held that the statute was not overly broad as written. Justice Scalia noted specifically that offers to engage in illegal transactions are categorically excluded from First Amendment protection, and he characterized the speech of an individual claiming to be in possession of child pornography in this category of unprotected speech.","sumSrc":"Oyez","by":{"1":"17"}},{"t":"case","label":"Zauderer v. Office of Disciplinary Counsel of the Supreme Court","cite":"471 U.S. 626","y":1985,"id":"1984/83-2166","sc":1,"ar":3,"sum":"The reprimand is sustainable to the extent that it is based on appellant's advertisement involving his terms of representation in drunken driving cases and on the omission of information regarding his contingent-fee arrangements in his Dalkon Shield advertisement. But insofar as the reprimand is based on appellant's use of an illustration in his advertisement and his offer of legal advice, the reprimand violated his …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"passim","4":"11, 12, 17, 25"}},{"t":"const","label":"Amendment XIV","clauses":[["due-process-14","Due Process Clause (Fourteenth Amendment)"]],"by":{"1":"1, 7","2":"11"}},{"t":"usc","label":"21 U.S.C. § 343","url":"https://www.law.cornell.edu/uscode/text/21/343","subs":["(q)(5)(H)","(r)(6)(C)"],"by":{"1":"30, 30"}},{"t":"usc","label":"29 U.S.C. § 627","url":"https://www.law.cornell.edu/uscode/text/29/627","by":{"1":"30"}},{"t":"usc","label":"29 U.S.C. § 657","url":"https://www.law.cornell.edu/uscode/text/29/657","subs":["(c)(1)"],"by":{"1":"30"}},{"t":"usc","label":"42 U.S.C. § 300-7","url":"https://www.law.cornell.edu/uscode/text/42/300-7","subs":["(c)"],"by":{"1":"32"}},{"t":"usc","label":"42 U.S.C. § 2000","url":"https://www.law.cornell.edu/uscode/text/42/2000","subs":["(e)"],"by":{"1":"30"}},{"t":"case","label":"Abbott Labs. v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"2":"28"}},{"t":"case","label":"Babbitt v. UFW Nat’l Union","cite":"442 U.S. 289","y":1979,"id":"1978/78-225","sc":1,"sum":"Appellees (a farmworkers' union, a union agent, farmworkers, and a union supporter) brought suit in Federal District Court in Arizona seeking a declaration of the unconstitutionality of various provisions of Arizona's farm labor statute, as well as of the entire statute, and an injunction against \"its enforcement. A three-judge court ruled unconstitutional on various grounds the provisions (1) specifying procedures …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15, 20"}},{"t":"case","label":"Cal., Dep’t of Educ. v. Bennett","cite":"833 F.2d 827","y":1987,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/833/827/","by":{"2":"30"}},{"t":"case","label":"Desert Outdoor Advert., Inc. v. City of Oakland","cite":"506 F.3d 798","y":2007,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/506/798/","by":{"2":"25"}},{"t":"case","label":"Doe v. Bolton","cite":"410 U.S. 179","y":1973,"id":"1971/70-40","sc":1,"sum":"Georgia law proscribes an abortion except as performed by a duly licensed Georgia physician when necessary in \"his best clinical judgment\" becausecontinued pregnancy would endanger a pregnant woman's life or injure her health; the fetus would likely be barn with a serious defect; or the pregnancy resulted from rape. § 26-1202 (a) of Ga. Criminal Code. In addition to a requirement that the patient be a Georgia …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"21"}},{"t":"case","label":"Harris v. Quinn","cite":"134 S. Ct. 2618","y":2014,"id":"2013/11-681","sc":1,"sum":"The Court held that the First Amendment prohibits the collection of union dues from home health care providers who do not wish to join a union.","sumSrc":"Oyez","by":{"2":"16"}},{"t":"case","label":"Lopez v. Candaele","cite":"630 F.3d 775","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/630/775/","by":{"2":"8"}},{"t":"case","label":"LSO, Ltd. v. Stroh","cite":"205 F.3d 1146","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/205/1146/","by":{"2":"9"}},{"t":"case","label":"Lujan v. Defs. of Wildlife","cite":"504 U.S. 555","y":1992,"id":"1991/90-1424","sc":1,"sum":"Even if the Court were to assume that the agency-funded projects at issue threatened listed species, there was no proof that these actions would produce \"actual or imminent\" injuries to particular respondents who might some day wish to visit the foreign countries in question.","sumSrc":"Oyez","by":{"2":"18"}},{"t":"case","label":"MTM, Inc. v. Baxley","cite":"420 U.S. 452","y":1974,"id":"1974/73-1119","sc":1,"sum":"This Court has no jurisdiction over an appeal under 28 U. S. C. § 1253 from a three-judge District Court's order denying injunctive relief against enforcement of a state-court temporary injunction under the Alabama nuisance statute closing appellant's theater, where the three-judge court did not reach the merits of appellant's constitutional attack on the nuisance statute but instead based its order on the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Nat’l Inst. of Family & Life Advocates v. Harris","cite":"839 F.3d 823","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/823/","by":{"2":"2, 3"}},{"t":"case","label":"Nat’l Park Hosp. Ass’n v. DOI","cite":"538 U.S. 803","y":2003,"id":"2002/02-196","sc":1,"sum":"The Court held that the controversy was not yet ripe for judicial resolution.","sumSrc":"Oyez","by":{"2":"23, 24, 27"}},{"t":"case","label":"Pennsylvania v. West Virginia","cite":"262 U.S. 553","y":1923,"id":"scdb/1922-218","sc":1,"sum":"1. A justiciable controversy between States, in the sense of the Judiciary Article, is presented when the plaintiff State, relying on the Commerce Clause of the Constitution, seeks to enjoin the defendant State from consummating a purpose, evinced by her statutory enactment, and about to be carried out by her officials, of withdrawing natural gas from an established current of commerce moving from her territory into …","sumSrc":"Headnote (U.S. Reports)","by":{"2":"22"}},{"t":"case","label":"Pierce v. Soc’y of Sisters","cite":"268 U.S. 510","y":1925,"id":"1900-1940/268us510","sc":1,"sum":"The unanimous Court held that \"the fundamental liberty upon which all governments in this Union repose excludes any general power of the State to standardize its children by forcing them to accept instruction from public teachers only.\".","sumSrc":"Oyez","by":{"2":"17, 18"}},{"t":"case","label":"Railway Mail Ass’n v. Corsi","cite":"326 U.S. 88","y":1945,"id":"scdb/1944-100","sc":1,"sum":"Section 43 of the New York Civil Rights Law forbids any \"labor organization\" to deny any person membership by reason of his race, color or creed, or to deny any member, by reason of race, color or creed, equal treatment in designation for employment, promotion or dismissal by any employer; other sections prescribe penalties and enforcement procedure. Appellant Railway Mail Association, an organization of regular and …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"8, 9"}},{"t":"case","label":"Renne v. Geary","cite":"501 U.S. 312","y":1991,"id":"1990/90-769","sc":1,"sum":"The question whether §6(b) violates the First Amendment is not justiciable in this case, since respondents have not demonstrated a live controversy ripe for resolution by the federal courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"2, 18, 19, 20, 27"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"sum":"The Court held that the case presented an actual controversy, as the Georgia statute could interfere with Steffel’s exercise of his constitutional rights even if he was not arrested. Because the United States’ involvement in Vietnam, which Steffel was protesting, was reduced, the issue of whether or not the case still presented an active controversy would be decided by the lower court on remand.","sumSrc":"Oyez","by":{"2":"14"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds Int’l Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"2":"23"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus, ___ U.S. ___","cite":"134 S. Ct. 2334","y":2014,"id":"2013/13-193","sc":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"2":"13, 14, 15, 16, 18"}},{"t":"case","label":"Tex. v. United States","cite":"523 U.S. 296","y":1998,"id":"1997/97-29","sc":1,"sum":"The Court held that Texas's claim is not ripe for adjudication.","sumSrc":"Oyez","by":{"2":"12"}},{"t":"case","label":"Thomas v. Anchorage Equal Rights Comm’n","cite":"220 F.3d 1134","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/220/1134/","by":{"2":"7, 8, 9, 24"}},{"t":"case","label":"Thomas v. Union Carbide Agric. Prods. Co.","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) requires manufacturers of pesticides, as a precondition for registering a pesticide, to submit research data to the Environmental Protection Agency (EPA) concerning the product's health, safety, and environmental effects, and authorizes EPA to use previously submitted data in considering an application for registration of a similar product by another …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Toilet Goods Ass’n v. Gardner","cite":"387 U.S. 158","y":1967,"id":"1966/336","sc":1,"sum":"Pre-enforcement judicial review of the regulation involved here is not appropriate as the controversy is not ripe for adjudication under the standards set forth in Abbott Laboratories v. Gardner, ante, p. 136.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"29, 30"}},{"t":"case","label":"Virginia v. Am. Booksellers Ass’n","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"9, 22, 28","4":"3"}},{"t":"case","label":"Wolfon v. Brammer","cite":"616 F.3d 1045","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/1045/","by":{"2":"9"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"2":"13, 14, 16, 20"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"2":"2, 11, 16"}},{"t":"const","label":"Article III","clauses":[["judicial-vesting","Judicial Vesting Clause"],["cases-controversies","Cases or Controversies (Justiciability)"],["original-jurisdiction","Original and Appellate Jurisdiction"],["treason","Treason Clause"]],"by":{"2":"1, 2, 19, 21, 31"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","by":{"2":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 28","url":"https://www.law.cornell.edu/rules/frcp/rule_28","subs":["(j)"],"by":{"2":"10, 20"}},{"t":"usc","label":"42 U.S.C. § 1395cc","url":"https://www.law.cornell.edu/uscode/text/42/1395cc","subs":["(a)(1)(N)(iii)"],"by":{"3":"42"}},{"t":"usc","label":"49 U.S.C. § 32908","url":"https://www.law.cornell.edu/uscode/text/49/32908","subs":["(b)"],"by":{"3":"48"}},{"t":"reg","label":"12 C.F.R. § 1026.1","url":"https://www.ecfr.gov/current/title-12/section-1026.1","subs":["(d)(2)"],"by":{"3":"48"}},{"t":"reg","label":"21 C.F.R. pt. 101","url":"https://www.ecfr.gov/current/title-21/part-101","by":{"3":"48"}},{"t":"reg","label":"21 C.F.R. pt. 201","url":"https://www.ecfr.gov/current/title-21/part-201","by":{"3":"43"}},{"t":"reg","label":"21 C.F.R. § 201.56","url":"https://www.ecfr.gov/current/title-21/section-201.56","by":{"3":"48"}},{"t":"reg","label":"21 C.F.R. § 201.57","url":"https://www.ecfr.gov/current/title-21/section-201.57","by":{"3":"48"}},{"t":"reg","label":"45 C.F.R. § 164.520","url":"https://www.ecfr.gov/current/title-45/section-164.520","subs":["(b)(1)"],"by":{"3":"42"}},{"t":"case","label":"Reply Br. of Appellant, First Resort v. Herrera","cite":"860 F.3d 1263","y":2017,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/860/1263/","by":{"3":"54"}},{"t":"case","label":"Rumsfeld v. Forum for Academic & Institutional Rights, Inc.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"sum":"The Supreme Court, in a unanimous opinion written by Chief Justice John Roberts, held that the Solomon Amendment regulated conduct, not speech, and was therefore constitutional. Including military recruiters in receptions and interviews does not necessarily indicate university endorsement of the recruiters, so requiring their inclusion does not constitute compelled speech in violation of the First Amendment.","sumSrc":"Oyez","by":{"4":"10"}},{"t":"case","label":"Sprietsma v. Mercury Marine","cite":"537 U.S. 51","y":2002,"id":"2002/01-706","sc":1,"sum":"The Court held 8-0 that neither the text nor the intent of the FBSA preempts Sprietsma's common law claims, either explicitly or implicitly.","sumSrc":"Oyez","by":{"4":"8"}}]};